+function RegistrationField({
+  copyValue,
+  description,
+  label,
+  value,
+}: Readonly<{
+  copyValue?: string;
+  description?: string;
+  label: string;
+  value: ReactNode;
+}>) {
+  return (
+    <div>
+      <dt className="text-sm text-kumo-subtle">{label}</dt>
+      <dd className="mt-1">
+        <div className="flex min-w-0 items-start gap-2">
